import{_ as i,o as t,c as n,ae as o}from"./chunks/framework.vXWZTEWX.js";const h=JSON.parse('{"title":"ADR 028: Migration to gemini-embedding-001 (3072 Dimensions)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/028-embedding-model-migration.md","filePath":"adr/028-embedding-model-migration.md"}'),a={name:"adr/028-embedding-model-migration.md"};function r(d,e,s,l,c,g){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-028-migration-to-gemini-embedding-001-3072-dimensions" tabindex="-1">ADR 028: Migration to gemini-embedding-001 (3072 Dimensions) <a class="header-anchor" href="#adr-028-migration-to-gemini-embedding-001-3072-dimensions" aria-label="Permalink to &quot;ADR 028: Migration to gemini-embedding-001 (3072 Dimensions)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h2><p>2026-03-04</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Since the release of Google Genkit v1.28.0, the previous identifier <code>text-embedding-004</code> (and its alias <code>embedding-001</code>) became unregistered in the <code>@genkit-ai/google-genai</code> plugin. Attempts to use these identifiers resulted in a 404 error from the Google AI SDK.</p><p>Through registry inspection, it was discovered that the new official identifier for embeddings is <code>googleai/gemini-embedding-001</code>.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We decided to:</p><ol><li><strong>Switch to <code>googleai/gemini-embedding-001</code></strong>: This is the current supported model in Genkit 1.28.0.</li><li><strong>Upgrade to 3072 Dimensions</strong>: The <code>gemini-embedding-001</code> model operates at 3072 dimensions by default, compared to the 768 dimensions of <code>text-embedding-004</code>.</li><li><strong>Update Global Configuration</strong>: Set <code>EMBEDDING_DIMENSIONS: 3072</code> in <code>genkit.config.ts</code>.</li><li><strong>Standardize Environment Variables</strong>: Use <code>GOOGLE_API_KEY</code> alongside <code>GOOGLE_GENAI_API_KEY</code> for better compatibility with newer plugins.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li><strong>Higher Fidelity</strong>: 3072 dimensions provide a richer semantic representation than 768 dimensions.</li><li><strong>Breaking Change for DB</strong>: Existing vectors stored in the <code>requirements</code> table (768-D) are now incompatible with new query vectors (3072-D).</li><li><strong>Storage Increase</strong>: Per-record storage for embeddings will increase by approximately 4x.</li></ul><h3 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h3><ul><li><strong>Data Flush Required</strong>: Users must re-process their PDFs to populate the database with 3072-D vectors.</li><li><strong>Standardized Setup</strong>: Adoption of <code>GOOGLE_API_KEY</code> aligns the project with standard Google Cloud/AI conventions.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://github.com/firebase/genkit/issues" target="_blank" rel="noreferrer">Genkit Issue: Embedding identifier change</a></li><li><a href="https://ai.google.dev/gemini-api/docs/models/gemini#embedding" target="_blank" rel="noreferrer">Gemini Embedding Model Documentation</a></li></ul>',18)])])}const u=i(a,[["render",r]]);export{h as __pageData,u as default};
